const labels={Speech:'人声',Music:'音乐',Silence:'静音',Beep:'提示音',Tone:'音调',Singing:'歌声',Laughter:'笑声',Applause:'掌声',Whoosh:'掠过声',Explosion:'爆炸声',Click:'点击声',Noise:'噪声',Siren:'警报声','Sine wave':'正弦音','Electronic music':'电子音乐'};
export function audioReport(data){const lines=['音轨分析（模型候选，请听原声核对）',data.notice||''];if(data.mode==='speech'){lines.push('语音转录：'+(data.result?.text||'未返回文字'));for(const c of data.result?.chunks||[]){const [a,b]=c.timestamp||[];lines.push(`${Number.isFinite(a)?a.toFixed(2):'?'}–${Number.isFinite(b)?b.toFixed(2):'?'} 秒：${c.text||''}`)}}else for(const s of data.segments||[]){lines.push(`\n${s.start.toFixed(2)}–${s.end.toFixed(2)} 秒`);lines.push(s.candidates.length?s.candidates.map(c=>`${labels[c.label]||'声音候选'}（${c.label}），模型分数 ${c.score.toFixed(3)}，不是准确率`).join('\n'):'近静音；未生成声音名称')}return lines.join('\n')}
